// Original procedural soundscape. Shares the game's user-unlocked AudioContext.
export function createAmbientAudio({getContext}){
 let context=null,nodes=[],sources=[],voices=new Set(),master,waves,city,engine,engineTone,noiseBuffer,nextBird=0,nextStep=0,bird=0,running=false;
 function keep(node){nodes.push(node);return node}
 function source(node){sources.push(node);return keep(node)}
 function stop(){for(const node of [...sources,...voices]){try{node.stop()}catch{}try{node.disconnect()}catch{}}for(const node of nodes)try{node.disconnect()}catch{}nodes=[];sources=[];voices.clear();context=null;noiseBuffer=null;running=false}
 function gain(value){const node=keep(context.createGain());node.gain.value=value;return node}
 function filter(type,hz){const node=keep(context.createBiquadFilter());node.type=type;node.frequency.value=hz;node.Q.value=.6;return node}
 function build(ctx){context=ctx;master=gain(0);master.connect(context.destination);const length=Math.floor(context.sampleRate*3);noiseBuffer=context.createBuffer(1,length,context.sampleRate);const data=noiseBuffer.getChannelData(0);let seed=4281,last=0;for(let n=0;n<length;n++){seed=(seed*1664525+1013904223)>>>0;last=(last+((seed/4294967296)*2-1)*.03)/1.03;data[n]=last*4}
  const noise=source(context.createBufferSource());noise.buffer=noiseBuffer;noise.loop=true;const low=filter('lowpass',900),swell=gain(.6);waves=gain(0);noise.connect(low);low.connect(swell);swell.connect(waves);waves.connect(master);const lfo=source(context.createOscillator()),depth=gain(.28);lfo.frequency.value=.16;lfo.connect(depth);depth.connect(swell.gain);
  const town=filter('lowpass',500);city=gain(0);noise.connect(town);town.connect(city);city.connect(master);engine=gain(0);engineTone=source(context.createOscillator());engineTone.type='triangle';engineTone.frequency.value=70;const muffler=filter('lowpass',260);engineTone.connect(muffler);muffler.connect(engine);engine.connect(master);noise.start();lfo.start();engineTone.start();nextBird=context.currentTime+1;nextStep=context.currentTime;running=true;
 }
 function chirp(volume,night){const osc=context.createOscillator(),voice=context.createGain(),time=context.currentTime+.02,hz=night?2900:1600+(bird++%5)*210;voices.add(osc);osc.type='sine';osc.frequency.setValueAtTime(hz,time);osc.frequency.exponentialRampToValueAtTime(hz*(night?1.03:1.6),time+.08);osc.frequency.exponentialRampToValueAtTime(hz*.9,time+.17);voice.gain.setValueAtTime(.0001,time);voice.gain.exponentialRampToValueAtTime(Math.max(.0002,volume*.11),time+.025);voice.gain.exponentialRampToValueAtTime(.0001,time+.22);osc.connect(voice);voice.connect(master);osc.onended=()=>{voices.delete(osc);osc.disconnect();voice.disconnect()};osc.start(time);osc.stop(time+.24)}
 function step(){const voice=context.createBufferSource(),envelope=context.createGain(),low=context.createBiquadFilter(),time=context.currentTime;voice.buffer=noiseBuffer;voices.add(voice);low.type='lowpass';low.frequency.value=330;envelope.gain.setValueAtTime(.15,time);envelope.gain.exponentialRampToValueAtTime(.0001,time+.11);voice.connect(low);low.connect(envelope);envelope.connect(master);voice.onended=()=>{voices.delete(voice);voice.disconnect();low.disconnect();envelope.disconnect()};voice.start(time,0,.12);voice.stop(time+.13)}
 return {update(mix,{enabled=false,volume=35}={}){let ctx;try{ctx=getContext()}catch{stop();return false}if(!enabled||!ctx||ctx.state!=='running'||volume<=0){stop();return false}try{if(context!==ctx||!running){stop();build(ctx)}const t=context.currentTime;master.gain.setTargetAtTime(Math.max(0,Math.min(100,volume))/100*.65,t,.15);waves.gain.setTargetAtTime(mix.sea*.55,t,.7);city.gain.setTargetAtTime(mix.town*.4,t,.7);engine.gain.setTargetAtTime(mix.engine*.12,t,.25);engineTone.frequency.setTargetAtTime(mix.engineHz,t,.35);
   if(t>=nextBird&&(mix.birds||mix.crickets)){chirp(mix.birds||mix.crickets,!!mix.crickets);nextBird=t+(mix.crickets?2.8:4.5)+(bird%3)}if(mix.footsteps&&t>=nextStep){step();nextStep=t+.55}return true;
  }catch{stop();return false}},stop,isRunning(){return running},destroy(){stop()}};
}
